// PayMe can only hand control back through an https link. A payment page
// opened with this flag asks the payment site to point PayMe at an app-only
// path on its own host. The app owns that path and maps the link back to the
// normal result page, so the result shows inside the waiting-room WebView.
const APP_RETURN_PARAM = 'app_return';
const APP_RETURN_VALUE = 'heals';
const APP_RETURN_PATH = '/app-return/heals';
const RETURN_PAGE = /^\/(completed|payme-fail)$/;

interface UrlParts {
  origin: string;
  path: string;
  query: string;
}

const splitUrl = (url?: string | null): UrlParts | null => {
  if (typeof url !== 'string') {
    return null;
  }
  const match = /^(https?:\/\/[^/?#]+)([^?#]*)(?:\?([^#]*))?/i.exec(url.trim());
  if (!match) {
    return null;
  }
  return {
    origin: match[1].toLowerCase(),
    path: match[2].replace(/\/+$/, ''),
    query: match[3] ?? '',
  };
};

const hasAppReturnFlag = (query: string): boolean =>
  query.split('&').some(pair => pair.split('=')[0] === APP_RETURN_PARAM);

export const withAppReturnFlag = (url: string): string => {
  const trimmed = url.trim();
  const hashIndex = trimmed.indexOf('#');
  const base = hashIndex === -1 ? trimmed : trimmed.slice(0, hashIndex);
  const hash = hashIndex === -1 ? '' : trimmed.slice(hashIndex);
  if (!/^https?:\/\//i.test(base)) {
    return url;
  }
  const queryIndex = base.indexOf('?');
  const query = queryIndex === -1 ? '' : base.slice(queryIndex + 1);
  if (hasAppReturnFlag(query)) {
    return url;
  }
  let separator = '&';
  if (queryIndex === -1) {
    separator = '?';
  } else if (query === '') {
    separator = '';
  }
  return `${base}${separator}${APP_RETURN_PARAM}=${APP_RETURN_VALUE}${hash}`;
};

// Returns the payment result page for a PayMe return link that belongs to the
// transaction in payUrl. Any other link returns null and is left alone.
export const paymentPageFromAppReturnUrl = (
  link: string | null | undefined,
  payUrl: string,
): string | null => {
  const linkParts = splitUrl(link);
  const payParts = splitUrl(payUrl);
  if (!linkParts || !payParts || linkParts.origin !== payParts.origin) {
    return null;
  }
  if (payParts.path === '') {
    return null;
  }
  const prefix = `${APP_RETURN_PATH}${payParts.path}`;
  if (!linkParts.path.startsWith(prefix)) {
    return null;
  }
  const page = linkParts.path.slice(prefix.length);
  if (!RETURN_PAGE.test(page)) {
    return null;
  }
  const query = linkParts.query === '' ? '' : `?${linkParts.query}`;
  return withAppReturnFlag(`${payParts.origin}${payParts.path}${page}${query}`);
};

import {
  paymentPageFromAppReturnUrl,
  withAppReturnFlag,
} from '../src/screens/product-waiting-room/payment-return-url';

const PAY_URL =
  'https://payment-stg.heals.asia/payment/4fcb401c-2ed0-4266-bdaf-53533696f52e?lang=en';
const APP_PAY_URL = `${PAY_URL}&app_return=heals`;
const RETURN_BASE =
  'https://payment-stg.heals.asia/app-return/heals/payment/4fcb401c-2ed0-4266-bdaf-53533696f52e';
const PAGE_BASE =
  'https://payment-stg.heals.asia/payment/4fcb401c-2ed0-4266-bdaf-53533696f52e';

describe('payment return url', () => {
  it('marks the payment page as opened inside the app', () => {
    expect(withAppReturnFlag(PAY_URL)).toBe(APP_PAY_URL);
    expect(withAppReturnFlag('https://pay.example/payment/1')).toBe(
      'https://pay.example/payment/1?app_return=heals',
    );
    expect(withAppReturnFlag('https://pay.example/payment/1?lang=en#top')).toBe(
      'https://pay.example/payment/1?lang=en&app_return=heals#top',
    );
  });

  it('leaves a marked or non-web url unchanged', () => {
    expect(withAppReturnFlag(APP_PAY_URL)).toBe(APP_PAY_URL);
    expect(withAppReturnFlag('about:blank')).toBe('about:blank');
  });

  it('maps the PayMe success link to the completed page of this transaction', () => {
    expect(
      paymentPageFromAppReturnUrl(`${RETURN_BASE}/completed?lang=en`, APP_PAY_URL),
    ).toBe(`${PAGE_BASE}/completed?lang=en&app_return=heals`);
  });

  it('maps the PayMe failure link to the retry page and keeps the flag once', () => {
    expect(
      paymentPageFromAppReturnUrl(
        `${RETURN_BASE}/payme-fail?lang=zh-Hant&app_return=heals`,
        APP_PAY_URL,
      ),
    ).toBe(`${PAGE_BASE}/payme-fail?lang=zh-Hant&app_return=heals`);
  });

  it('ignores links that are not the return link of this transaction', () => {
    expect(
      paymentPageFromAppReturnUrl(`${PAGE_BASE}/completed?lang=en`, APP_PAY_URL),
    ).toBeNull();
    expect(
      paymentPageFromAppReturnUrl(
        'https://payment-stg.heals.asia/app-return/heals/payment/another-id/completed',
        APP_PAY_URL,
      ),
    ).toBeNull();
    expect(
      paymentPageFromAppReturnUrl(
        `${RETURN_BASE.replace('payment-stg', 'payment')}/completed`,
        APP_PAY_URL,
      ),
    ).toBeNull();
    expect(
      paymentPageFromAppReturnUrl(`${RETURN_BASE}/yedpay`, APP_PAY_URL),
    ).toBeNull();
    expect(
      paymentPageFromAppReturnUrl('heals://app-return/heals/completed', APP_PAY_URL),
    ).toBeNull();
    expect(paymentPageFromAppReturnUrl(undefined, APP_PAY_URL)).toBeNull();
  });
});

